from datetime import datetime

import pytest
from isoduration import add_duration


# ============================================================================
# Basic single components
# ============================================================================


class TestBasicComponents:
    """Test single duration components."""

    def test_years_single(self):
        assert add_duration(datetime(2020, 2, 29), "P1Y") == datetime(2021, 2, 28)

    def test_years_multiple(self):
        assert add_duration(datetime(2020, 1, 1), "P5Y") == datetime(2025, 1, 1)

    def test_months_single(self):
        assert add_duration(datetime(2025, 1, 15), "P1M") == datetime(2025, 2, 15)

    def test_months_multiple(self):
        assert add_duration(datetime(2025, 1, 1), "P12M") == datetime(2025, 12, 1)

    def test_weeks_single(self):
        assert add_duration(datetime(2025, 1, 1), "P1W") == datetime(2025, 1, 8)

    def test_weeks_multiple(self):
        assert add_duration(datetime(2025, 1, 1), "P2W") == datetime(2025, 1, 15)

    def test_days_single(self):
        assert add_duration(datetime(2025, 3, 10), "P1D") == datetime(2025, 3, 11)

    def test_days_multiple(self):
        assert add_duration(datetime(2025, 3, 10), "P3D") == datetime(2025, 3, 13)

    def test_hours_single(self):
        assert add_duration(datetime(2025, 1, 1, 10), "PT1H") == datetime(2025, 1, 1, 11)

    def test_hours_multiple(self):
        assert add_duration(datetime(2025, 1, 1, 10), "PT5H") == datetime(2025, 1, 1, 15)

    def test_minutes_single(self):
        assert add_duration(datetime(2025, 1, 1, 10, 30), "PT1M") == datetime(2025, 1, 1, 10, 31)

    def test_minutes_multiple(self):
        assert add_duration(datetime(2025, 1, 1, 10), "PT45M") == datetime(2025, 1, 1, 10, 45)

    def test_seconds_single(self):
        assert add_duration(datetime(2025, 1, 1, 10, 30, 45), "PT1S") == datetime(2025, 1, 1, 10, 30, 46)

    def test_seconds_multiple(self):
        assert add_duration(datetime(2025, 1, 1, 10), "PT30S") == datetime(2025, 1, 1, 10, 0, 30)


# ============================================================================
# Multi-component combinations
# ============================================================================


class TestMultipleComponents:
    """Test combinations of components."""

    def test_years_and_months(self):
        assert add_duration(datetime(2020, 1, 1), "P1Y2M") == datetime(2021, 3, 1)

    def test_years_months_days(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y2M3D") == datetime(2021, 3, 18)

    def test_days_and_time(self):
        assert add_duration(datetime(2025, 3, 10), "P1DT2H30M") == datetime(2025, 3, 11, 2, 30)

    def test_years_months_days_time(self):
        assert add_duration(datetime(2020, 1, 15, 10), "P1Y2M3DT4H30M") == datetime(2021, 3, 18, 14, 30)

    def test_all_time_components(self):
        assert add_duration(datetime(2025, 1, 1), "PT1H2M3S") == datetime(2025, 1, 1, 1, 2, 3)

    def test_weeks_and_days_separate(self):
        # Weeks and days are both date components but can be combined
        assert add_duration(datetime(2025, 1, 1), "P1W2D") == datetime(2025, 1, 10)


# ============================================================================
# Sign handling
# ============================================================================


class TestSignHandling:
    """Test positive and negative signs."""

    def test_explicit_positive_sign(self):
        assert add_duration(datetime(2025, 1, 15), "+P2D") == datetime(2025, 1, 17)

    def test_implicit_positive_no_sign(self):
        assert add_duration(datetime(2025, 1, 15), "P2D") == datetime(2025, 1, 17)

    def test_negative_sign_days(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    def test_negative_sign_months(self):
        assert add_duration(datetime(2025, 3, 15), "-P1M") == datetime(2025, 2, 15)

    def test_negative_sign_hours(self):
        assert add_duration(datetime(2025, 1, 1, 10), "-PT2H") == datetime(2025, 1, 1, 8)

    def test_negative_multiple_components(self):
        assert add_duration(datetime(2025, 3, 15, 10), "-P1M2DT3H") == datetime(2025, 2, 11, 7)


# ============================================================================
# Fractional parts
# ============================================================================


class TestFractionalParts:
    """Test fractional components (only last component can have fractions)."""

    def test_fractional_days_dot_separator(self):
        # 0.5 days = 12 hours
        assert add_duration(datetime(2025, 1, 1), "P0.5D") == datetime(2025, 1, 1, 12)

    def test_fractional_days_comma_separator(self):
        # 0.5 days = 12 hours
        assert add_duration(datetime(2025, 1, 1), "P0,5D") == datetime(2025, 1, 1, 12)

    def test_fractional_weeks(self):
        # 0.5 weeks = 3.5 days = 3 days 12 hours
        assert add_duration(datetime(2025, 1, 1), "P0.5W") == datetime(2025, 1, 4, 12)

    def test_fractional_hours(self):
        # 0.5 hours = 30 minutes
        assert add_duration(datetime(2025, 1, 1, 10), "PT0.5H") == datetime(2025, 1, 1, 10, 30)

    def test_fractional_minutes(self):
        # 0.5 minutes = 30 seconds
        assert add_duration(datetime(2025, 1, 1, 10), "PT0.5M") == datetime(2025, 1, 1, 10, 0, 30)

    def test_fractional_seconds(self):
        # 0.5 seconds = 500000 microseconds
        result = add_duration(datetime(2025, 1, 1, 10), "PT0.5S")
        assert result == datetime(2025, 1, 1, 10, 0, 0, 500000)

    def test_fractional_seconds_various_decimals(self):
        # PT1.5S = 1.5 seconds = 1 second 500000 microseconds
        result = add_duration(datetime(2025, 1, 1, 10), "PT1.5S")
        assert result == datetime(2025, 1, 1, 10, 0, 1, 500000)

    def test_fractional_with_leading_zeros(self):
        # 01.50 should be treated as 1.50
        result = add_duration(datetime(2025, 1, 1, 10), "PT01.50S")
        assert result == datetime(2025, 1, 1, 10, 0, 1, 500000)

    def test_fractional_multiple_decimal_places(self):
        # Microsecond precision test
        result = add_duration(datetime(2025, 1, 1), "PT0.000001S")
        assert result == datetime(2025, 1, 1, 0, 0, 0, 1)


# ============================================================================
# Day-of-month edge cases (overflow handling)
# ============================================================================


class TestDayOfMonthOverflow:
    """Test handling when target day doesn't exist in target month."""

    def test_january_31_plus_one_month_to_february(self):
        # Jan 31 + 1 month = Feb 29 (in leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_january_31_plus_one_month_to_february_non_leap(self):
        # Jan 31 + 1 month = Feb 28 (non-leap year)
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_march_31_minus_one_month_to_february(self):
        # Mar 31 - 1 month = Feb 29 (in leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_january_31_plus_thirteen_months(self):
        # Jan 31, 2024 + P1Y1M = Mar 29, 2025 (13 months in one step)
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 3, 29)

    def test_january_31_plus_one_year_then_one_month_step_order(self):
        # Combined years and months are applied together
        # Jan 31, 2024 + P1Y1M should be Mar 29, 2025
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 3, 29)

    def test_march_31_plus_zero_months_stays_march_31(self):
        assert add_duration(datetime(2025, 3, 31), "P0M") == datetime(2025, 3, 31)

    def test_time_preserved_during_month_overflow(self):
        # Time components should be preserved
        result = add_duration(datetime(2024, 1, 31, 15, 30, 45), "P1M")
        assert result == datetime(2024, 2, 29, 15, 30, 45)

    def test_fractional_day_plus_month_overflow(self):
        # Apply months first, then fractional days
        # Jan 31 + 1 month = Feb 29, then + 0.5 days = Feb 29 12:00
        result = add_duration(datetime(2024, 1, 31), "P1M0.5D")
        assert result == datetime(2024, 2, 29, 12)


# ============================================================================
# Negative durations (applying negated parts)
# ============================================================================


class TestNegativeDurations:
    """Test applying negative durations."""

    def test_negative_months_then_days(self):
        # Mar 1 - P1M1D = Feb 1 - 1 day = Jan 31
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_negative_months_with_overflow(self):
        # Mar 31 - P1M = Feb 29 (overflow on the negative side)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_years_and_months(self):
        # 2024-03-29 - P1Y1M = 2023-02-27 (13 months back from 2024-03-29)
        # Actually, Mar 29 going back 13 months lands on Feb 29, 2023, but that's a leap year
        # 2024-03-29 - 13 months = 2023-02-29
        assert add_duration(datetime(2024, 3, 29), "-P1Y1M") == datetime(2023, 2, 28)

    def test_negative_fractional_days(self):
        # 0.5 days = 12 hours
        result = add_duration(datetime(2025, 1, 2, 12), "-P0.5D")
        assert result == datetime(2025, 1, 2)


# ============================================================================
# Week constraints
# ============================================================================


class TestWeekConstraints:
    """Test that weeks cannot be combined with other date components."""

    def test_weeks_cannot_combine_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P2W3D")

    def test_weeks_cannot_combine_with_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1M2W")

    def test_weeks_cannot_combine_with_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1Y2W")

    def test_weeks_can_combine_with_time(self):
        # Weeks CAN combine with time components
        assert add_duration(datetime(2025, 1, 1), "P1WT2H") == datetime(2025, 1, 8, 2)


# ============================================================================
# Syntax validation
# ============================================================================


class TestSyntaxValidation:
    """Test parsing and syntax error detection."""

    def test_missing_p_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "1Y")

    def test_p_alone_no_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P")

    def test_pt_alone_no_time_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "PT")

    def test_p_with_t_but_no_time_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1DT")

    def test_lowercase_p_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "p1D")

    def test_lowercase_designators_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1d")

    def test_whitespace_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P 1D")

    def test_sign_on_component_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P-1D")

    def test_duplicate_year_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1Y2Y")

    def test_duplicate_month_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1M2M")

    def test_components_out_of_order(self):
        # Days before months is invalid
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1D2M")

    def test_time_before_date(self):
        # T should come after date components
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "PT1H1D")

    def test_no_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "")

    def test_multiple_decimal_points(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1.2.3D")

    def test_fraction_on_non_last_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1.5D2H")

    def test_fraction_on_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1.5Y")

    def test_fraction_on_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1.5M")

    def test_fraction_missing_digit_before_decimal(self):
        # At least one digit on each side of decimal
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P.5D")

    def test_fraction_missing_digit_after_decimal(self):
        # At least one digit on each side of decimal
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1.D")

    def test_no_digits_in_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "PD")

    def test_invalid_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1X")

    def test_m_before_t_is_months(self):
        # This should parse as months, not minutes - should be valid
        assert add_duration(datetime(2025, 1, 1), "P1MT2H") == datetime(2025, 2, 1, 2)

    def test_m_after_t_is_minutes(self):
        # This should parse as minutes - should be valid
        assert add_duration(datetime(2025, 1, 1, 10), "PT1M") == datetime(2025, 1, 1, 10, 1)


# ============================================================================
# Order of operations
# ============================================================================


class TestOrderOfOperations:
    """Test that components are applied in the correct order."""

    def test_months_then_days_affects_overflow(self):
        # Apply months first, so overflow happens during month change
        # Jan 31 + 1 month + 2 days = Feb 31 (overflow to Feb 29) + 2 days = Mar 2
        # But we apply months first to get Feb 29, then add 2 days = Mar 2
        result = add_duration(datetime(2024, 1, 31), "P1M2D")
        assert result == datetime(2024, 3, 2)

    def test_months_then_time_no_interaction(self):
        # Months don't affect time, applied separately
        result = add_duration(datetime(2024, 1, 15, 10, 30), "P1MT2H")
        assert result == datetime(2024, 2, 15, 12, 30)

    def test_weeks_then_time_no_interaction(self):
        result = add_duration(datetime(2025, 1, 1, 10), "P1WT2H")
        assert result == datetime(2025, 1, 8, 12)


# ============================================================================
# Datetime range boundaries
# ============================================================================


class TestDatetimeRanges:
    """Test that operations outside datetime range raise ValueError."""

    def test_overflow_to_year_too_large(self):
        # datetime.max is year 9999
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1D")

    def test_underflow_to_year_too_small(self):
        # datetime.min is year 1
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1D")

    def test_overflow_during_month_calculation(self):
        # 9999-12-31 + P1M should fail
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1M")

    def test_valid_near_max_boundary(self):
        # This should be fine
        result = add_duration(datetime(9999, 12, 30), "P1D")
        assert result == datetime(9999, 12, 31)

    def test_valid_near_min_boundary(self):
        # This should be fine
        result = add_duration(datetime(1, 1, 2), "-P1D")
        assert result == datetime(1, 1, 1)


# ============================================================================
# Microsecond precision
# ============================================================================


class TestMicrosecondPrecision:
    """Test microsecond-level precision."""

    def test_microsecond_addition(self):
        result = add_duration(datetime(2025, 1, 1, microsecond=100), "PT0.000001S")
        assert result == datetime(2025, 1, 1, microsecond=101)

    def test_microsecond_overflow_to_second(self):
        result = add_duration(datetime(2025, 1, 1, microsecond=999999), "PT0.000001S")
        assert result == datetime(2025, 1, 1, 0, 0, 1)

    def test_fractional_seconds_to_microseconds(self):
        result = add_duration(datetime(2025, 1, 1), "PT0.1S")
        assert result == datetime(2025, 1, 1, 0, 0, 0, 100000)

    def test_rounding_to_nearest_microsecond(self):
        # Rounding behavior - should round to nearest microsecond
        result = add_duration(datetime(2025, 1, 1), "PT0.0000005S")
        # 0.0000005 seconds = 0.5 microseconds, should round to 1 microsecond or 0?
        # The spec says "round any finer remainder to the nearest microsecond"
        # 0.5 rounds to 1 (banker's rounding or standard rounding)
        assert result.microsecond in [0, 1]  # Allow both rounding directions


# ============================================================================
# Leap year handling
# ============================================================================


class TestLeapYears:
    """Test handling of leap years."""

    def test_leap_year_february_29_exists(self):
        assert add_duration(datetime(2024, 2, 28), "P1D") == datetime(2024, 2, 29)

    def test_leap_year_february_29_plus_one_year_to_non_leap(self):
        result = add_duration(datetime(2024, 2, 29), "P1Y")
        assert result == datetime(2025, 2, 28)

    def test_non_leap_february_28_plus_one_year_to_leap(self):
        result = add_duration(datetime(2023, 2, 28), "P1Y")
        assert result == datetime(2024, 2, 28)

    def test_leap_year_sequence(self):
        # 2024 is leap, 2025-2027 are not, 2028 is leap
        assert add_duration(datetime(2024, 2, 29), "P4Y") == datetime(2028, 2, 29)


# ============================================================================
# Large values and edge cases
# ============================================================================


class TestLargeValues:
    """Test handling of large component values."""

    def test_large_number_of_days(self):
        result = add_duration(datetime(2020, 1, 1), "P365D")
        assert result == datetime(2020, 12, 31)

    def test_large_number_of_months(self):
        result = add_duration(datetime(2020, 1, 1), "P24M")
        assert result == datetime(2022, 1, 1)

    def test_leading_zeros_on_components(self):
        assert add_duration(datetime(2025, 1, 1), "P01D") == datetime(2025, 1, 2)
        assert add_duration(datetime(2025, 1, 1), "P001D") == datetime(2025, 1, 2)

    def test_large_hours(self):
        result = add_duration(datetime(2025, 1, 1), "PT100H")
        assert result == datetime(2025, 1, 5, 4)

    def test_large_seconds(self):
        result = add_duration(datetime(2025, 1, 1), "PT3661S")
        # 3661 seconds = 1 hour, 1 minute, 1 second
        assert result == datetime(2025, 1, 1, 1, 1, 1)


# ============================================================================
# Example from README
# ============================================================================


class TestReadmeExamples:
    """Test specific examples from the README."""

    def test_readme_example_p1y2m10dt2h30m(self):
        # Basic example from README
        result = add_duration(datetime(2020, 1, 15, 10), "P1Y2M10DT2H30M")
        assert result == datetime(2021, 3, 25, 12, 30)

    def test_readme_january_31_plus_p1m_equals_february_29(self):
        # Specific example from README
        result = add_duration(datetime(2024, 1, 31), "P1M")
        assert result == datetime(2024, 2, 29)

    def test_readme_february_29_plus_p1y1m_equals_march_29(self):
        # Specific example from README: "13 months in one step, not one year and then one month"
        result = add_duration(datetime(2024, 2, 29), "P1Y1M")
        assert result == datetime(2025, 3, 29)

    def test_readme_negative_march_31_minus_p1m_equals_february_29(self):
        # Negative example from README
        result = add_duration(datetime(2024, 3, 31), "-P1M")
        assert result == datetime(2024, 2, 29)

    def test_readme_negative_march_01_minus_p1m1d_equals_january_31(self):
        # Negative example from README
        result = add_duration(datetime(2024, 3, 1), "-P1M1D")
        assert result == datetime(2024, 1, 31)
